export const taskStatusGroup = (state: TaskState) =>
  Match.value(state).pipe(
    Match.when('NEW', () => 'NOT_STARTED' as const),
    Match.whenOr('DONE', 'CANCELLED', () => 'DONE' as const),
    Match.whenOr('IN_PROGRESS', 'WAITING', () => 'IN_PROGRESS' as const),
    Match.exhaustive,
  );
export const taskIsOverdue = (task: Task, referenceDate = '2026-10-05') =>
  taskStatusGroup(task.state) !== 'DONE' && task.dueDate !== undefined && task.dueDate < referenceDate;

