export const visibleWorkTasks = Effect.fn('Work.visibleTasks')(function* visibleTasks(
  tasks: readonly Task[],
  scope: OperationalScope,
) {
  const access = yield* ContextAccess;
  if (yield* contextGrant(scope, 'read_all')) {
    return tasks;
  }
  if (scope.legalEntityId === undefined) {
    return yield* referenceUnavailable();
  }
  const decisions = yield* access.resources({
    legalEntityId: scope.legalEntityId,
    principalId: scope.principalId,
    resources: tasks.map(({ ref }) => ref),
    tenantId: scope.tenantId,
  });
  if (
    decisions.length !== tasks.length ||
    decisions.some(
      (decision, index) =>
        decision.decision === 'unavailable' ||
        decision.key !==
          `${tasks[index]?.ref.moduleId}:${tasks[index]?.ref.resourceType}:${tasks[index]?.ref.resourceId}`,
    )
  ) {
    return yield* referenceUnavailable();
  }
  return tasks.filter((_, index) => decisions[index]?.decision === 'allowed');
});

